-- Migration 0008: Admissions
-- Project: Bright Future Academy (BFA) school platform
-- Run once, after migrations 0001 to 0007.
-- Everything runs in one transaction: if any statement fails, nothing is applied.
--
-- Design notes
--  * Application reference numbers look like APP/26/0001 and are generated by
--    the database. Admission numbers look like BFA/26/0001 (format read from
--    school_settings 'admission_number.format'). Both counters restart each year.
--    Admission numbers are generated by the backend when an approved applicant is
--    enrolled: generate_admission_number(<start year of the admission session>).
--  * These generator functions can be called by the backend only, not by browser keys.
--    Public applications therefore go through the backend (which also rate-limits them).
--  * Application status can only move along allowed paths (see check_application_transition).
--  * Uploaded documents live in a private storage bucket; this migration stores
--    only the path, type and size. Only PDF, JPEG and PNG up to 10 MB are accepted.
--  * Reviews are an append-only history.

begin;

-- ---------------------------------------------------------------
-- Number counters (one row per kind of number per year)
-- ---------------------------------------------------------------
create table public.number_counters (
  counter_key   text not null check (counter_key ~ '^[a-z_]+$'),
  counter_year  integer not null check (counter_year between 2000 and 2999),
  last_number   integer not null default 0 check (last_number >= 0),
  updated_at    timestamptz not null default now(),
  primary key (counter_key, counter_year)
);

-- Atomic: concurrent callers always receive different numbers
create or replace function public.next_counter_value(p_key text, p_year integer)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_next integer;
begin
  insert into public.number_counters (counter_key, counter_year, last_number)
  values (p_key, p_year, 1)
  on conflict (counter_key, counter_year)
  do update set last_number = public.number_counters.last_number + 1,
                updated_at = now()
  returning last_number into v_next;

  return v_next;
end;
$$;

-- BFA/26/0001: prefix, two-digit year, running number (format from school_settings)
create or replace function public.generate_admission_number(p_year integer default null)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_fmt          jsonb;
  v_year         integer;
  v_prefix       text;
  v_sep          text;
  v_year_digits  integer;
  v_seq_digits   integer;
  v_next         integer;
  v_seq_text     text;
begin
  select value into v_fmt
    from public.school_settings where key = 'admission_number.format';
  if v_fmt is null then
    raise exception 'The admission number format is not configured';
  end if;

  v_year        := coalesce(p_year, extract(year from now())::integer);
  v_prefix      := v_fmt ->> 'prefix';
  v_sep         := coalesce(v_fmt ->> 'separator', '/');
  v_year_digits := coalesce((v_fmt ->> 'year_digits')::integer, 2);
  v_seq_digits  := coalesce((v_fmt ->> 'sequence_digits')::integer, 4);

  v_next     := public.next_counter_value('admission', v_year);
  v_seq_text := v_next::text;
  -- Pad with zeros without ever cutting a long number short
  v_seq_text := repeat('0', greatest(v_seq_digits - length(v_seq_text), 0)) || v_seq_text;

  return v_prefix || v_sep || right(v_year::text, v_year_digits) || v_sep || v_seq_text;
end;
$$;

-- APP/26/0001: application reference shown to the applicant
create or replace function public.generate_application_reference()
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_year     integer := extract(year from now())::integer;
  v_next     integer;
  v_seq_text text;
begin
  v_next     := public.next_counter_value('application', v_year);
  v_seq_text := v_next::text;
  v_seq_text := repeat('0', greatest(4 - length(v_seq_text), 0)) || v_seq_text;
  return 'APP/' || right(v_year::text, 2) || '/' || v_seq_text;
end;
$$;

-- ---------------------------------------------------------------
-- admission_applications
-- ---------------------------------------------------------------
create table public.admission_applications (
  id                      uuid primary key default gen_random_uuid(),
  reference_number        text not null unique default public.generate_application_reference(),
  session_id              uuid not null references public.academic_sessions (id) on delete restrict,
  applying_class_id       uuid not null references public.classes (id) on delete restrict,
  campus_id               uuid not null references public.campuses (id) on delete restrict,

  first_name              text not null check (length(trim(first_name)) > 0),
  middle_name             text,
  last_name               text not null check (length(trim(last_name)) > 0),
  gender                  text check (gender in ('female', 'male')),
  date_of_birth           date not null,
  nationality             text,
  state_of_origin         text,
  home_address_enc        text,
  previous_school         text,
  previous_class          text,

  guardian_first_name     text not null check (length(trim(guardian_first_name)) > 0),
  guardian_last_name      text not null check (length(trim(guardian_last_name)) > 0),
  guardian_relationship   text not null
                          check (guardian_relationship in ('mother', 'father', 'guardian', 'grandparent', 'sibling', 'other')),
  guardian_phone          text not null check (length(trim(guardian_phone)) > 0),
  guardian_whatsapp       text,
  guardian_email          text
                          check (guardian_email is null
                                 or guardian_email ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'),

  consent_given           boolean not null check (consent_given),
  consent_at              timestamptz not null default now(),
  consent_version         text,

  status                  text not null default 'submitted'
                          check (status in ('submitted', 'under_review', 'approved', 'rejected',
                                            'waitlisted', 'enrolled', 'withdrawn')),
  waitlist_position       integer check (waitlist_position is null or waitlist_position > 0),
  submitted_at            timestamptz not null default now(),
  decision_by             uuid references public.profiles (id) on delete restrict,
  decision_at             timestamptz,
  decision_reason         text,
  converted_student_id    uuid unique references public.students (id) on delete restrict,
  enrolled_at             timestamptz,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),

  constraint admission_applications_decision_check
    check (status not in ('approved', 'rejected', 'waitlisted', 'enrolled')
           or (decision_by is not null and decision_at is not null)),
  constraint admission_applications_rejected_check
    check (status <> 'rejected' or length(trim(coalesce(decision_reason, ''))) >= 5),
  constraint admission_applications_waitlist_check
    check (status <> 'waitlisted' or waitlist_position is not null),
  -- An application is 'enrolled' exactly when it points to the student created from it
  constraint admission_applications_enrolled_check
    check ((status = 'enrolled') = (converted_student_id is not null)),
  constraint admission_applications_enrolled_at_check
    check (status <> 'enrolled' or enrolled_at is not null)
);

create index admission_applications_session_id_idx on public.admission_applications (session_id);
create index admission_applications_class_id_idx on public.admission_applications (applying_class_id);
create index admission_applications_campus_id_idx on public.admission_applications (campus_id);
create index admission_applications_status_idx on public.admission_applications (status);
create index admission_applications_decision_by_idx on public.admission_applications (decision_by);

-- The same child cannot be applied for twice in one session while an application is live
create unique index admission_applications_no_duplicates
  on public.admission_applications
  (session_id, lower(last_name), lower(first_name), date_of_birth, guardian_phone)
  where status not in ('rejected', 'withdrawn');

-- One place per waitlist position for each class and session
create unique index admission_applications_waitlist_position_unique
  on public.admission_applications (applying_class_id, session_id, waitlist_position)
  where status = 'waitlisted';

-- Status can only move along allowed paths
create or replace function public.check_application_transition()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.status is distinct from old.status then
    if not (
      (old.status = 'submitted'    and new.status in ('under_review', 'rejected', 'withdrawn')) or
      (old.status = 'under_review' and new.status in ('approved', 'rejected', 'waitlisted', 'withdrawn')) or
      (old.status = 'waitlisted'   and new.status in ('approved', 'rejected', 'withdrawn')) or
      (old.status = 'approved'     and new.status in ('enrolled', 'withdrawn')) or
      (old.status = 'rejected'     and new.status = 'under_review')
    ) then
      raise exception 'An application cannot move from % to %', old.status, new.status;
    end if;
  end if;
  return new;
end;
$$;

create trigger admission_applications_check_transition
  before update of status on public.admission_applications
  for each row execute function public.check_application_transition();

-- ---------------------------------------------------------------
-- admission_documents (files are in a private storage bucket)
-- ---------------------------------------------------------------
create table public.admission_documents (
  id              uuid primary key default gen_random_uuid(),
  application_id  uuid not null references public.admission_applications (id) on delete restrict,
  document_type   text not null
                  check (document_type in ('birth_certificate', 'passport_photo', 'previous_report',
                                           'transfer_letter', 'immunisation_record', 'guardian_id', 'other')),
  storage_path    text not null check (length(trim(storage_path)) > 0),
  file_name       text not null check (length(trim(file_name)) > 0),
  mime_type       text not null check (mime_type in ('application/pdf', 'image/jpeg', 'image/png')),
  size_bytes      bigint not null check (size_bytes > 0 and size_bytes <= 10485760),
  status          text not null default 'uploaded'
                  check (status in ('uploaded', 'accepted', 'rejected')),
  reviewed_by     uuid references public.profiles (id) on delete restrict,
  reviewed_at     timestamptz,
  review_note     text,
  uploaded_at     timestamptz not null default now(),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint admission_documents_reviewed_check
    check (status = 'uploaded' or (reviewed_by is not null and reviewed_at is not null)),
  constraint admission_documents_rejected_check
    check (status <> 'rejected' or length(trim(coalesce(review_note, ''))) > 0)
);

create index admission_documents_application_id_idx on public.admission_documents (application_id);
create index admission_documents_reviewed_by_idx on public.admission_documents (reviewed_by);

-- ---------------------------------------------------------------
-- admission_reviews: append-only history of review steps and decisions
-- ---------------------------------------------------------------
create table public.admission_reviews (
  id              uuid primary key default gen_random_uuid(),
  application_id  uuid not null references public.admission_applications (id) on delete restrict,
  stage           text not null
                  check (stage in ('document_check', 'academic_review', 'interview', 'decision')),
  decision        text not null
                  check (decision in ('recommended', 'not_recommended', 'approved', 'rejected',
                                      'waitlisted', 'info_requested')),
  reviewer_id     uuid not null references public.profiles (id) on delete restrict,
  comment         text,
  reviewed_at     timestamptz not null default now(),
  constraint admission_reviews_comment_check
    check (decision not in ('not_recommended', 'rejected', 'info_requested')
           or length(trim(coalesce(comment, ''))) > 0)
);

create index admission_reviews_application_id_idx on public.admission_reviews (application_id);
create index admission_reviews_reviewer_id_idx on public.admission_reviews (reviewer_id);

create trigger admission_reviews_append_only
  before update or delete on public.admission_reviews
  for each row execute function public.prevent_row_modification();

-- ---------------------------------------------------------------
-- updated_at triggers
-- ---------------------------------------------------------------
create trigger admission_applications_set_updated_at
  before update on public.admission_applications
  for each row execute function public.set_updated_at();

create trigger admission_documents_set_updated_at
  before update on public.admission_documents
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------
-- Keep number generators and helpers away from browser keys
-- ---------------------------------------------------------------
revoke execute on function public.next_counter_value(text, integer)
  from public, anon, authenticated;
revoke execute on function public.generate_admission_number(integer)
  from public, anon, authenticated;
revoke execute on function public.generate_application_reference()
  from public, anon, authenticated;
revoke execute on function public.check_application_transition()
  from public, anon, authenticated;

-- ---------------------------------------------------------------
-- Row Level Security: ON for every table (policies come in Step 8)
-- ---------------------------------------------------------------
alter table public.number_counters         enable row level security;
alter table public.admission_applications  enable row level security;
alter table public.admission_documents     enable row level security;
alter table public.admission_reviews       enable row level security;

commit;